func (r *QueryResolver) Carrier(ctx context.Context, id string) (*carrier.Carrier, error) {
	authCtx, err := r.RequirePermission(ctx, permission.ResourceCarrier, permission.OpRead)
	if err != nil {
		return nil, err
	}

	carrierID, err := pulid.MustParse(id)
	if err != nil {
		return nil, err
	}

	return r.CarrierService.Get(ctx, repositories.GetCarrierByIDRequest{
		ID:         carrierID,
		TenantInfo: base.TenantInfo(authCtx),
		CarrierFilterOptions: repositories.CarrierFilterOptions{
			IncludeState:             true,
			IncludeContacts:          true,
			IncludeInsurancePolicies: true,
		},
	})
}
